#import "presentation/FYInlineCardRenderer.h"
#import "FYInlineCardRenderTestFacts.h"
#import <objc/runtime.h>
@interface NativeRenderSource : NSObject <FYInlineCardRenderSource>
@property(nonatomic,strong) FYInlineCardRenderer *renderer;
@property(nonatomic,strong) FYInlineLayoutEngine *inlineLayoutEngine;
@property(nonatomic,strong) NSMutableArray<NSPanel *> *inlineTranslationPanels,*inlineLongCardPanels;
@property(nonatomic,strong) NSPanel *inlineExpandedReadingPanel,*inlineOverflowPanel;
@property(nonatomic,strong) CardContentFact *replacement;
@property(nonatomic) NSUInteger fontReads,styleReads,colors,wires,rebuilds;
@property(nonatomic) BOOL selected;
@end
@implementation NativeRenderSource
- (instancetype)init{if((self=[super init])){self.renderer=[FYInlineCardRenderer new];self.inlineLayoutEngine=[FYInlineLayoutEngine defaultEngine];self.inlineTranslationPanels=[NSMutableArray new];self.inlineLongCardPanels=[NSMutableArray new];}return self;}
- (NSParagraphStyle *)inlineLongCardBodyStyle{self.styleReads++;return [self.renderer inlineLongCardBodyStyleWithSource:self];}
- (NSFont *)inlineLongCardBodyFont{self.fontReads++;return [self.renderer inlineLongCardBodyFontWithSource:self];}
- (CGFloat)inlineLongCardBodyLineHeight{return [self.renderer inlineLongCardBodyLineHeightWithSource:self];}
- (NSColor *)inlinePanelTextColor{self.colors++;return [NSColor colorWithSRGBRed:.2 green:.3 blue:.4 alpha:.6];}
- (NSColor *)inlinePanelTitleColor{return NSColor.brownColor;}
- (NSColor *)inlinePanelFillColor{return NSColor.whiteColor;}
- (NSColor *)inlinePanelBorderColor{return NSColor.brownColor;}
- (NSFont *)inlinePanelFontOfSize:(CGFloat)s{return [NSFont systemFontOfSize:s];}
- (NSFont *)inlinePanelFontOfSize:(CGFloat)s weight:(NSFontWeight)w{return [NSFont systemFontOfSize:s weight:w];}
- (NSColor *)inlineCardInkColor{return NSColor.blackColor;}
- (NSColor *)inlineCardMintColor{return NSColor.greenColor;}
- (NSColor *)inlineCardRimColor{return NSColor.grayColor;}
- (NSColor *)inlineCardLineColor{return NSColor.brownColor;}
- (NSString *)inlineCardTitleForBlockText:(NSString *)t{return [FYInlineLayoutEngine shortTitleForBlockText:t];}
- (NSTextField *)label:(NSString *)t font:(NSFont *)f color:(NSColor *)c{CardLabelFact *label=[CardLabelFact new];label.stringValue=t;label.font=f;label.textColor=c;return (NSTextField *)label;}
- (NSTextField *)inlineCompactEntryLabel:(NSString *)t font:(NSFont *)f color:(NSColor *)c{return [self.renderer inlineCompactEntryLabel:t font:f color:c source:self];}
- (void)applyInlineChromeToContent:(NSView *)v cornerRadius:(CGFloat)r{[self.renderer applyInlineChromeToContent:v cornerRadius:r source:self];}
- (void)applyInlineCompactEntryChromeToContent:(NSView *)v cornerRadius:(CGFloat)r{[self.renderer applyInlineCompactEntryChromeToContent:v cornerRadius:r source:self];}
- (void)applyInlineLongCardBody:(NSString *)t toLabel:(NSTextField *)l cardWidth:(CGFloat)w placement:(FYInlinePlacement *)p{[self.renderer applyInlineLongCardBody:t toLabel:l cardWidth:w placement:p source:self];}
- (NSView *)inlineLongCardContentForTranslation:(NSString *)t size:(NSSize)s selected:(BOOL)selected compact:(BOOL)compact placement:(FYInlinePlacement *)p{self.rebuilds++;return (NSView *)self.replacement;}
- (FYInlinePlacement *)inlinePlacementForLongCardFrame:(NSRect)f translation:(NSString *)t{return [self.renderer inlinePlacementForLongCardFrame:f translation:t expandedReading:NO source:self];}
- (NSAttributedString *)inlinePanelAttributedText:(NSString *)t font:(NSFont *)f{return [self.renderer inlinePanelAttributedText:t font:f source:self];}
- (void)applyInlineTextColor:(NSColor *)c toView:(NSView *)v{[self.renderer applyInlineTextColor:c toView:v source:self];}
- (BOOL)inlineHostBlockID:(NSString *)identity isSelectedForItem:(OCRTextItem *)item{return self.selected;}
- (void)inlineCardWirePanelThroughHost:(NSPanel *)p item:(OCRTextItem *)item translation:(NSString *)t frame:(NSRect)f stableBlockID:(NSString *)identity{self.wires++;}
@end
int main(void){@autoreleasepool{
 Check(NSApp==nil,@"minimum native renderer link creates no app/view/control/window");NativeRenderSource *s=[NativeRenderSource new];unsigned int n=0;Ivar *v=class_copyIvarList(FYInlineCardRenderer.class,&n);free(v);Check(n==0,@"renderer is stateless without resource/cache/source ownership");
 FYInlinePlacement *p=[FYInlinePlacement new];p.font=[NSFont systemFontOfSize:22 weight:NSFontWeightBold];NSMutableParagraphStyle *style=[NSMutableParagraphStyle new];style.lineSpacing=8;p.paragraphStyle=style;p.panelPadding=7;CardLabelFact *label=[CardLabelFact new];NSString *text=@"合成正文\r\n次行";[s.renderer applyInlineLongCardBody:text toLabel:(NSTextField *)label cardWidth:130 placement:p source:s];Check(!s.fontReads&&!s.styleReads&&s.colors==1&&label.font==p.font&&label.frame.size.width==116&&label.frame.size.height==ExpectedBodyHeight(text,130,7,p.font,p.paragraphStyle),@"explicit placement font/style avoid fallback reads and use real original measure");Check([label.attributedStringValue.string isEqual:FYInlineNormalizeTranslationParagraphs(text)]&&[label.attributedStringValue attribute:NSParagraphStyleAttributeName atIndex:0 effectiveRange:NULL]==style,@"body preserves canonical paragraphs and explicit style alias in attributes");
 [s.renderer applyInlineLongCardBody:nil toLabel:(NSTextField *)label cardWidth:30 placement:nil source:s];Check(s.fontReads==1&&s.styleReads==1&&label.frame.size.width==80&&label.frame.size.height==ExpectedBodyHeight(nil,30,18,label.font,[s.inlineLayoutEngine longBodyParagraphStyle])&&label.frame.size.height>=22&&label.attributedStringValue.length==0,@"nil placement/translation uses original18 padding/fallback fonts/min80 width/actual glyph ceil+4 above22");
 CGRect frame=CGRectMake(10,20,240,180);p=[s.renderer inlinePlacementForLongCardFrame:frame translation:text expandedReading:YES source:s];Check(p.titleBandHeight==37&&p.expandedReading&&p.measuredContentHeight==[s.inlineLayoutEngine measuredBodyHeight:text placement:p width:240]+4&&p.scrollable==(p.measuredContentHeight>p.bodyViewportHeight+.5),@"actual native placement shares real engine measurement and strict scroll gate");InlinePanelLayout mapped=[s.renderer inlinePanelLayoutFromPlacement:p];Check(CGRectEqualToRect(mapped.frame,p.translationFrame)&&mapped.font==p.font&&mapped.cornerRadius==12,@"original raw layout/font mapping direct");
 p=[s inlinePlacementForLongCardFrame:frame translation:text];CardPanelFact *panel=[CardPanelFact new];panel.frame=frame;panel.contentView=LongContent(frame,p);CardContentFact *existing=panel.contentView;CardScrollFact *scroll=existing.subviews[0];s.replacement=[CardContentFact new];[s.renderer updateInlineLongCard:(NSPanel *)panel translation:text item:nil frame:frame compact:NO placement:p source:s];Check(panel.contentView==existing&&s.rebuilds==0&&s.wires==1&&panel.displays==1&&scroll.contentView.scrolls==1&&scroll.reflects==1,@"actual reused card keeps native object identity, clamps scroll and rewires before display");s.selected=YES;[s.renderer updateInlineLongCard:(NSPanel *)panel translation:text item:nil frame:frame compact:NO placement:p source:s];Check(s.rebuilds==1&&panel.contentView==s.replacement&&s.wires==2,@"actual selected-state mismatch rebuilds via original factory boundary");
 CardLabelFact *shortLabel=[CardLabelFact new];shortLabel.font=p.font;shortLabel.stringValue=@"old";CardContentFact *shortCard=[CardContentFact new];shortCard.frame=CGRectZero;shortCard.layer=[CardLayerFact new];shortCard.subviews=@[shortLabel];panel.contentView=shortCard;InlinePanelLayout layout;layout.frame=CGRectMake(11,22,100,40);layout.labelFrame=CGRectMake(10,5,80,30);layout.font=p.font;layout.cornerRadius=7;[s.renderer updateInlinePanel:(NSPanel *)panel translation:@"new" sourceText:@"source" sourceFrame:CGRectZero windowFrame:frame layout:layout source:s];Check(CGRectEqualToRect(panel.frame,layout.frame)&&!panel.display&&CGRectEqualToRect(shortCard.frame,CGRectMake(0,0,100,40))&&CGRectEqualToRect(shortLabel.frame,layout.labelFrame)&&[shortLabel.attributedStringValue.string isEqual:@"new"]&&shortCard.layer.cornerRadius==7,@"actual short update keeps frame/content/text/label/chrome native sequence");
 CardLabelFact *compact=(CardLabelFact *)[s.renderer inlineCompactEntryLabel:@"label" font:p.font color:NSColor.redColor source:s];Check([compact.stringValue isEqual:@"label"]&&compact.font==p.font&&compact.shadow.shadowBlurRadius==2.5&&NSEqualSizes(compact.shadow.shadowOffset,NSMakeSize(0,-1))&&fabs(compact.shadow.shadowColor.alphaComponent-.85)<.001,@"actual compact label uses original native shadow and explicit font/color");
 CardContentFact *patch=[CardContentFact new];patch.patch=YES;patch.layer=[CardLayerFact new];patch.showsDragHint=YES;CardPanelFact *patchPanel=[CardPanelFact new];patchPanel.contentView=patch;[s.inlineTranslationPanels addObject:(NSPanel *)patchPanel];[s.renderer refreshInlinePanelAppearanceWithSource:s];Check(CGColorEqualToColor(patch.layer.backgroundColor,NSColor.whiteColor.CGColor)&&[patch.normalBorderColor isEqual:NSColor.brownColor]&&[patch.dragHintColor isEqual:[s inlinePanelTextColor]]&&patch.showsDragHint,@"appearance updates native patch style without changing drag hint state");
 CardLabelFact *colored=[CardLabelFact new];colored.attributedStringValue=[[NSAttributedString alloc]initWithString:@"text" attributes:@{NSForegroundColorAttributeName:[NSColor colorWithSRGBRed:0 green:0 blue:0 alpha:.25]}];colored.textColor=NSColor.blackColor;[s.renderer applyInlineTextColor:NSColor.redColor toView:(NSView *)colored source:s];Check(fabs(colored.textColor.alphaComponent-.25)<.001&&[colored.attributedStringValue.string isEqual:@"text"],@"actual recursive color preserves existing alpha and characters");CardContentFact *badge=[CardContentFact new];badge.longCard=YES;badge.subviews=@[colored];badge.selectedBadgeBox=(NSView *)colored;NSAttributedString *before=colored.attributedStringValue;[s.renderer applyInlineTextColor:NSColor.blueColor toView:(NSView *)badge source:s];Check(colored.attributedStringValue==before,@"selected badge retains original color during recursive update");
 __weak NativeRenderSource *weak;@autoreleasepool{NativeRenderSource *q=[NativeRenderSource new];weak=q;CardLabelFact *l=[CardLabelFact new];[q.renderer applyInlineLongCardBody:@"lease" toLabel:(NSTextField *)l cardWidth:160 placement:nil source:q];}Check(!weak,@"renderer does not retain borrowed source after native synchronous body call");Check(NSApp==nil,@"real fonts/attributes/primitives and native facts remain headless; UI constructors only compiled");printf("PASS InlineCardRendererTests: %lu checks;actual native body/measure/update/appearance,real fonts,no UI objects\n",(unsigned long)checks);
}return 0;}
